class Solution {
  public int[] scoreValidator(String[] events) {
    int score = 0, counter = 0;
    for (String e : events) {
      if (e.equals("W")) counter++;
      else if (e.equals("WD") || e.equals("NB")) score++;
      else score += Integer.parseInt(e);
      if (counter == 10) break;
    }
    return new int[] {score, counter};
  }
}
